mapper.select:
SELECT id, name, description, duration, total_score AS totalScore, status, addtime
FROM exampaper
WHERE id = #{paperId}

SELECT q.id, q.paper_id AS paperId, p.name AS paperName, q.question_name AS questionName, q.question_type AS questionType, q.options_json AS optionsJson, q.answer, q.analysis, q.score, q.sort, q.addtime FROM examquestion q LEFT JOIN exampaper p ON p.id = q.paper_id
AND q.question_name LIKE CONCAT('%', #{keyword}, '%')
AND q.paper_id = #{paperId}
ORDER BY q.paper_id DESC, q.sort ASC, q.id ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM examquestion q
AND q.question_name LIKE CONCAT('%', #{keyword}, '%')
AND q.paper_id = #{paperId}

