mapper.select:
SELECT r.id, r.paper_id AS paperId, p.name AS paperName, r.user_id AS userId, u.username, r.score, r.correct_count AS correctCount, r.wrong_count AS wrongCount, r.start_time AS startTime, r.submit_time AS submitTime, r.addtime FROM examrecord r LEFT JOIN exampaper p ON p.id = r.paper_id LEFT JOIN t_users u ON u.id = r.user_id
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND r.user_id = #{userId}
ORDER BY r.submit_time DESC, r.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM examrecord r LEFT JOIN exampaper p ON p.id = r.paper_id LEFT JOIN t_users u ON u.id = r.user_id
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND r.user_id = #{userId}
